                        const slot = self.cellar_next;
                        self.cellar_next += 1;
                        return slot;
                    }
                    self.cellar_next += 1;
                }
            }

            var i: usize = 0;
            while (i < self.cellar_start) : (i += 1) {
                if (self.buckets[i] == null) {
                    return i;
                }
            }

            return null;
        }

        pub fn get(self: *Self, key: K) ?V {
            const index = self.hash(key) % self.cellar_start;

            var current_idx: ?usize = index;
